KG42.register("clusters-0ee17e72e94c41247e00b101",{"id":"25-p2p_ancillary_bidding::v142-d-CL005","paper":"25-p2p_ancillary_bidding","label":"Ancillary service participating entities and adjustable directions","record":{"cluster_id":"v142-d-CL005","label":"Ancillary service participating entities and adjustable directions","market_meaning":"Consumers can provide ancillary services to the utility by increasing or decreasing electricity consumption, and prosumers can do so by increasing or decreasing generation or consumption; the applicable research scope is demand-side community services on a minute-to-hour scale.","mechanism_ids":["v141-a-M03-ancillary-service"],"market_types":["DEM"],"process_stages":["participation"],"scope_disposition":"compatible","scope_explanation":"The two chains describe the capabilities of different entities in the same ancillary service mechanism; the difference in the action scopes of consumers and prosumers is retained, and the time range follows the source limitation and is not expanded to second-by-second frequency response.","assembly_status":"assembled","boundary_rationale":"Participation capability and permitted adjustment direction can be expressed independently; specific demand publication, bid quantity, procurement, and remuneration are assembled separately, and participation permission itself does not prove that the customer actually submitted a quote.","chain_bindings":[{"chain_id":"v141-c-R012","ownership":"primary","role":"core","rationale":"Clarify the scope in which consumers participate in the service through changes in electricity consumption."},{"chain_id":"v141-c-R013","ownership":"primary","role":"core","rationale":"Supplement the prosumer's generation or consumption adjustment capability, while maintaining the entity distinction."}],"connections":[{"connection_id":"v142-d-CL005-CON01","from_chain_id":"v141-c-R012","to_chain_id":"v141-c-R013","kind":"complementary_scope","from_refs":["v141-c-R012::phi::v141-c-R012-C001"],"to_refs":["v141-c-R013::phi::v141-c-R013-C001"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E03"],"rationale":"The source collectively refers to the two types of entities as customers while separately limiting their adjustable electricity consumption and generation activities; therefore, the participation scope is expressed jointly without merging the entity identities."}],"object_mappings":[],"gaps":[{"gap_id":"v142-d-CL005-G01","category":"unverified_source","description":"The evidence for participating entities, adjustment direction, and service time range remains unverified; the completeness of this cluster pertains only to the described qualitative participation rule.","chain_ids":["v141-c-R012","v141-c-R013"],"object_refs":["v141-c-R012::phi::v141-c-R012-C001","v141-c-R013::phi::v141-c-R013-C001"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E03"],"proposal_ids":[],"required_work":"Follow-up manual verification should check the entity capabilities and time range, and the participation rule should not be expanded into specific technical certification or guaranteed procurement."}]},"rule_refs":["25-p2p_ancillary_bidding::v141-c-R012","25-p2p_ancillary_bidding::v141-c-R013"],"unresolved_rule_refs":[],"node_ids":["COMP-7b77631c556e010b"]});
